def test_symbol_has_no_dict():
    import sympy
    s = sympy.Symbol('s')
    # Ensure __slots__ is defined and does not include '__dict__'
    assert hasattr(s, '__slots__')
    assert '__dict__' not in s.__slots__
    # Accessing __dict__ should raise AttributeError
    try:
        s.__dict__
    except AttributeError:
        pass
    else:
        raise AssertionError("Symbol instance should not have __dict__")
